'use strict';
window.OrthodoxSaints=(()=>{
  let promise,cleanup=()=>{};
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  const safe=url=>{try{const u=new URL(url);return u.protocol==='https:'?esc(u.href):'#';}catch{return '#';}};
  const link=(url,text)=>`<a href="${safe(url)}" target="_blank" rel="noopener noreferrer">${esc(text)}</a>`;
  const paragraphs=text=>String(text||'').split(/\n\s*\n/).map(p=>`<p>${esc(p).replace(/\n/g,'<br>')}</p>`).join('');
  const months=['January','February','March','April','May','June','July','August','September','October','November','December'];
  async function load(id){
    if(window.OrthodoxSite){const data=await window.OrthodoxResources.json('page-data/saints/'+(id||'index')+'.json');return {...data,images:new Map(data.images.map(image=>[image.saintId,image])),biographies:new Map(data.biographies.map(profile=>[profile.saintId,profile]))};}
    return promise||(promise=Promise.all(['saints.json','saints-biographies.json','saint-images.json','saints-additions.json','saints-reference-additions.json'].map(async file=>{const response=await fetch('content/'+file);if(!response.ok)throw Error('Saints library unavailable');return response.json();})).then(([data,expanded,artwork,additions,references])=>{
      data.saints.push(...additions.saints,...references.saints);
      if(new Set(data.saints.map(saint=>saint.id)).size!==data.saints.length)throw Error('Duplicate Saint records');
      data.images=new Map([...artwork.images,...references.images].map(image=>[image.saintId,image]));
      data.biographies=new Map([...expanded.profiles,...additions.profiles,...references.profiles].map(profile=>[profile.saintId,profile]));
      const sources=new Map(data.sources.map(source=>[source.id,source]));
      for(const source of [...expanded.sources,...additions.sources,...references.sources])if(!sources.has(source.id))sources.set(source.id,source);
      data.sources=[...sources.values()];
      return data;
    }).catch(error=>{promise=null;throw error;}));
  }
  const commemoration=saint=>saint.commemoration.label||(saint.commemoration.month&&saint.commemoration.day?months[saint.commemoration.month-1]+' '+saint.commemoration.day:'See published commemoration');
  function unmount(){cleanup();cleanup=()=>{};}
  async function mount(ctx){
    unmount();const {root,id,params=new URLSearchParams(),lessons=[]}=ctx,controller=new AbortController();cleanup=()=>controller.abort();root.innerHTML='<p role="status">Loading Saints…</p>';
    let data;try{data=await load(id);}catch{if(controller.signal.aborted)return;root.innerHTML='<h1>Saints</h1><p>The Saints library could not be loaded.</p><button type="button" data-saints-retry>Retry</button>';root.querySelector('button').onclick=()=>mount(ctx);return;}
    if(controller.signal.aborted||!root.isConnected)return;
    root.addEventListener('click',event=>{const anchor=event.target.closest('[data-saints-scroll]');if(!anchor)return;event.preventDefault();const target=root.querySelector('#'+CSS.escape(anchor.dataset.saintsScroll));if(!target)return;if(target.tagName==='DETAILS')target.open=true;target.tabIndex=-1;target.scrollIntoView();target.focus({preventScroll:true});},{signal:controller.signal});
    const sourceMap=new Map(data.sources.map(s=>[s.id,s])),lessonMap=new Map(lessons.map(l=>[l.id,l]));
    const sourceMeta=source=>[source.author,source.work||source.title,source.edition,source.translator].filter(Boolean).map(esc).join(' · ');
    function attribution(reading){const s=sourceMap.get(reading.sourceId);return `<footer class="saint-reading-source">${s?sourceMeta(s):''}${reading.locator?`<p>${esc(reading.locator)}</p>`:''}${s?`<p>${link(s.url,'Read complete source')} · ${esc(s.rights)}</p>`:''}</footer>`;}
    const deathLabels={'martyr':'Martyrdom in the source account','other-death':'Other recorded death','uncertain':'Death circumstances uncertain','mixed':'Mixed accounts / joint profile','not-applicable':'Angelic beings'};
    function allBlocks(profile){return [...(profile?.sections||[]).flatMap(s=>s.blocks),...(profile?.chronology||[]).map(event=>event.event)];}
    function refsFor(block){return block.sourceRefs?.length?block.sourceRefs:[{sourceId:block.sourceId,locator:block.locator}];}
    function biography(profile,sourceList,hasAdditionalReadings){
      if(!profile)return '';const numbers=new Map(sourceList.map((source,index)=>[source.id,index+1]));
      const citations=block=>refsFor(block).map(ref=>`<a href="#saint-source-${esc(ref.sourceId)}" data-saints-scroll="saint-source-${esc(ref.sourceId)}" aria-label="Source ${numbers.get(ref.sourceId)}">[${numbers.get(ref.sourceId)}]</a> <span class="saint-citation-locator">${esc(sourceMap.get(ref.sourceId)?.type||'Source reading')} · ${esc(ref.locator)}</span>`).join(' · ');
      const block=(item,scope)=>`<div class="saint-biography-block" data-study-scope="saint-biography-${esc(scope)}" data-biography-kind="${esc(item.kind)}" data-scripture-source="${esc(item.sourceId)}" ${item.edition==='kjv'?'data-scripture-edition="kjv"':''}>${item.kind==='quotation'?`<blockquote class="quoted-reading">${paragraphs(item.text)}</blockquote>${item.context?`<p class="saint-reading-context">${esc(item.context)}</p>`:''}`:`<div class="saint-biography-summary">${paragraphs(item.text).replace(/<p>/g,'<p data-annotatable>')}</div>`}<p class="saint-biography-citations">${citations(item)}</p></div>`;
      return `<nav class="saint-section-nav" aria-label="Saint biography sections">${profile.sections.map(section=>`<a href="#saint-${esc(section.id)}" data-saints-scroll="saint-${esc(section.id)}">${esc(section.title)}</a>`).join('')}<a href="#saint-chronology" data-saints-scroll="saint-chronology">Chronology</a>${hasAdditionalReadings?'<a href="#saint-native-readings" data-saints-scroll="saint-native-readings">Additional source readings</a>':''}</nav><div class="saint-death-record"><strong>Death / martyrdom</strong><p>${esc(profile.death.label)}</p><a href="#saint-death" data-saints-scroll="saint-death">Read circumstances and sources</a></div>${profile.sections.map(section=>`<section id="saint-${esc(section.id)}" class="saint-biography-section" tabindex="-1"><h2>${esc(section.title)}</h2>${section.blocks.map((item,i)=>block(item,section.id+'-'+i)).join('')}</section>`).join('')}<section id="saint-chronology" class="saint-chronology" tabindex="-1"><h2>Chronology</h2><ol>${profile.chronology.map((entry,i)=>`<li><strong>${esc(entry.date)}</strong>${block(entry.event,'chronology-'+i)}</li>`).join('')}</ol></section>`;
    }
    if(id){
      const saint=data.saints.find(s=>s.id===id);if(!saint){root.innerHTML='<h1>Saint not found</h1><a href="#/saints">Saints</a>';return;}
      const expanded=data.biographies.get(saint.id),image=data.images.get(saint.id);
      const refs=[saint.sourceId,...(saint.excerpt?[saint.excerpt.sourceId]:[]),...(saint.summary.sourceRefs||[]).map(ref=>ref.sourceId),...allBlocks(expanded).flatMap(block=>refsFor(block).map(ref=>ref.sourceId)),...(saint.additionalSourceIds||[]),...(saint.readings||[]).map(r=>r.sourceId)],sources=[...new Set(refs)].map(id=>sourceMap.get(id)).filter(Boolean);
      const related=(saint.relatedLessons||[]).map(id=>lessonMap.get(id)).filter(Boolean);
      root.innerHTML=`<article class="saint-reader"><p><a href="#/saints">Saints</a></p><header class="saint-profile-heading">${window.OrthodoxVisuals.picture(image,{title:saint.name,deferCredit:true})}<div class="saint-profile-facts"><h1>${esc(saint.name)}</h1>${saint.aliases?.length?`<p>${saint.aliases.map(esc).join(' · ')}</p>`:''}<dl class="saint-facts"><div><dt>Period</dt><dd>${esc(saint.dates||saint.era)}</dd></div><div><dt>Region</dt><dd>${esc(saint.region)}</dd></div><div><dt>Titles / vocation</dt><dd>${saint.types.map(esc).join(' · ')}</dd></div><div><dt>Commemoration</dt><dd>${esc(commemoration(saint))}</dd></div></dl></div></header><section data-scripture-source="${esc(saint.sourceId)}"><h2>Introduction</h2><div class="saint-summary">${paragraphs(saint.summary.text)}</div><p>${link(sourceMap.get(saint.sourceId)?.url,'Read the published life')} <a href="#saint-sources" data-saints-scroll="saint-sources">[1]</a></p>${saint.excerpt?`<blockquote class="saint-short-excerpt" data-scripture-source="${esc(saint.excerpt.sourceId)}" ${saint.excerpt.edition==='kjv'||saint.excerpt.sourceId==='sp-kjv'?'data-scripture-edition="kjv"':''}>${paragraphs(saint.excerpt.text)}</blockquote><p class="saint-excerpt-label">${sourceMap.has(saint.excerpt.sourceId)?sourceMeta(sourceMap.get(saint.excerpt.sourceId)):'Published excerpt'} · ${esc(saint.excerpt.locator)}</p>`:''}</section>${biography(expanded,sources,Boolean(saint.readings?.length))}<div id="saint-native-readings" tabindex="-1"></div>${saint.readings?.length?`<section class="saint-native-readings"><h2>Published readings</h2>${saint.readings.map((reading,i)=>`<details class="saint-reading" ${i===0?'open':''}><summary><span>${esc(reading.title)}</span><small>${reading.text.trim().split(/\s+/).length.toLocaleString()} words · ${esc(reading.genre||'Source reading')}</small></summary><div data-scripture-source="${esc(reading.sourceId)}" ${reading.edition==='kjv'?'data-scripture-edition="kjv"':''}><p class="saint-reading-context">${esc(reading.context||'')}</p><blockquote>${paragraphs(reading.text)}</blockquote>${attribution(reading)}</div></details>`).join('')}</section>`:''}${related.length?`<section><h2>Related lessons</h2><ul>${related.map(l=>`<li><a href="#/lesson/${esc(l.id)}">${esc(l.title)}</a></li>`).join('')}</ul></section>`:''}<section id="saint-sources"><h2>Sources</h2>${window.OrthodoxVisuals.artworkSource(image)}<p>${esc(saint.sourceTitle)}</p><details class="saint-context"><summary>Source context and historical limits</summary><p>${esc(saint.context)}</p><p>${esc(saint.summary.reason)}</p><p>Text checked against the identified source. No theological review is claimed.</p></details><p class="saint-calendar-note">${esc(data.calendarNote)}</p><ol>${sources.map(s=>`<li id="saint-source-${esc(s.id)}" tabindex="-1" data-scripture-source="${esc(s.id)}">${link(s.url,s.title)}<p>${sourceMeta(s)}</p><p>${esc(s.type||'')} · ${esc(s.tradition||'')}</p>${s.context?`<p>${esc(s.context)}</p>`:''}<p>${esc(s.rights)}</p>${s.rightsNote?`<p>${esc(s.rightsNote)}</p>`:''}</li>`).join('')}</ol></section></article>`;
      window.OrthodoxVisuals.bindArtwork(root,image,saint.name,controller.signal);window.ScripturePreviews?.enhance(root);return;
    }
    const q={q:params.get('q')||'',era:params.get('era')||'',region:params.get('region')||'',type:params.get('type')||'',month:params.get('month')||'',death:params.get('death')||'',native:params.get('native')==='yes'?'yes':''};let display=params.get('view')==='timeline'?'timeline':'cards';
    const unique=field=>[...new Set(data.saints.flatMap(s=>Array.isArray(s[field])?s[field]:[s[field]]))].filter(Boolean).sort();
    const select=(key,label,values)=>`<label>${label}<select id="saints-${key}"><option value="">All</option>${values.map(v=>`<option value="${esc(v)}" ${q[key]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;
    root.innerHTML=`<div class="page-heading"><h1>Saints</h1></div><p class="result-count">${data.saints.length} sourced profiles · <a href="#saints-context" data-saints-scroll="saints-context">Sources and scope</a></p><form class="saints-filters" role="search"><label class="saints-query">Search saints<input id="saints-q" type="search" value="${esc(q.q)}" placeholder="Name, place, title, or life" autocomplete="off"></label>${select('era','Period',unique('era'))}${select('region','Region',unique('region'))}${select('type','Title / vocation',unique('types'))}<label>Death / martyrdom<select id="saints-death"><option value="">All accounts</option>${Object.entries(deathLabels).map(([value,label])=>`<option value="${value}" ${q.death===value?'selected':''}>${label}</option>`).join('')}</select></label><label>Commemoration month<select id="saints-month"><option value="">All months</option>${months.map((name,i)=>`<option value="${i+1}" ${q.month===String(i+1)?'selected':''}>${name}</option>`).join('')}</select></label><label class="saints-native-filter"><input type="checkbox" id="saints-native" ${q.native?'checked':''}> With published source readings</label><button type="button" class="secondary" data-saints-reset>Reset filters</button></form><p id="saints-count" class="result-count" aria-live="polite"></p><div id="saints-results" class="saints-grid"></div><details id="saints-context" class="saint-context"><summary>Sources and scope</summary><p>${esc(data.scope)}</p><p>${esc(data.calendarNote)}</p><p>Profiles identify the published ecclesiastical account. A source's hagiographic account is distinguished from a modern critical biography. Profiles retain their source references; published readings retain their wording and edition. No theological review is claimed.</p></details>`;
    root.querySelector('.saints-filters').insertAdjacentHTML('beforebegin',`<div class="saints-view-switch" role="group" aria-label="Saints view"><button class="secondary" type="button" data-saints-view="cards" aria-pressed="${display==='cards'}">Profile cards</button><button class="secondary" type="button" data-saints-view="timeline" aria-pressed="${display==='timeline'}">Historical timeline</button></div>`);
    const on=(event,fn)=>root.addEventListener(event,fn,{signal:controller.signal});
    window.OrthodoxVisuals.bindArtwork(root,null,'',controller.signal);
    root.addEventListener('click',event=>{const card=event.target.closest('[data-saint-card]');if(card&&!event.target.closest('a,button')&&window.getSelection()?.isCollapsed!==false)location.hash='/saint/'+card.dataset.saintCard;},{signal:controller.signal});
    const timelineBands=['Old Testament and biblical','Apostolic and New Testament','Early Church and patristic','Byzantine','Medieval and early modern','Modern','Other source-dated periods'];
    function timelineBand(saint){const text=norm(saint.era+' '+(saint.dates||''));if(/old testament|biblical/.test(text))return timelineBands[0];if(/apostolic|subapostolic|first century|gospel period|early christian tradition/.test(text))return timelineBands[1];if(/early church|patristic|early christian|second.century|third.century|fourth.century|fifth.century|sixth.century/.test(text))return timelineBands[2];if(/byzantine|seventh.century|eighth.century|ninth.century|tenth.century/.test(text))return timelineBands[3];if(/medieval|eleventh.century|twelfth.century|thirteenth.century|fourteenth.century|fifteenth.century|sixteenth.century|seventeenth.century/.test(text))return timelineBands[4];if(/modern|eighteenth.century|nineteenth.century|twentieth.century/.test(text))return timelineBands[5];return timelineBands[6];}
    function timeline(found){const groups=new Map(timelineBands.map(band=>[band,[]]));for(const saint of found)groups.get(timelineBand(saint)).push(saint);return `<section class="saints-timeline" aria-label="Saints historical timeline"><p class="saints-timeline-note">Broad bands organize the profiles for browsing. Each card retains the source-qualified period and date wording; uncertain dates are not converted into exact points.</p>${timelineBands.filter(band=>groups.get(band).length).map((band,index)=>`<section class="saints-era"><header><span class="saints-era-marker" aria-hidden="true"></span><h2>${esc(band)}</h2><span>${groups.get(band).length} profile${groups.get(band).length===1?'':'s'}</span></header><div class="saints-era-list">${groups.get(band).map(s=>`<article><p class="saints-timeline-dates">${esc(s.dates||s.era)}</p><h3><a href="#/saint/${esc(s.id)}">${esc(s.name)}</a></h3><p>${esc(s.region)}</p><p class="saints-timeline-source-era">Source period: ${esc(s.era)}</p></article>`).join('')}</div></section>`).join('')}</section>`;}
    let deepSearch=null,searchPending=false;async function searchLives(){if(!window.OrthodoxSite||deepSearch||searchPending||!q.q.trim())return;searchPending=true;try{const rows=await window.OrthodoxResources.json('page-data/saints/search.json');deepSearch=new Map(rows.map(r=>[r.id,r.text]));if(!controller.signal.aborted)render();}catch{}finally{searchPending=false;}}
    function render(){
      searchLives();const words=norm(q.q).trim().split(/\s+/).filter(Boolean),found=data.saints.filter(s=>(!q.era||s.era===q.era)&&(!q.region||s.region===q.region)&&(!q.type||s.types.includes(q.type))&&(!q.month||s.commemoration.month===Number(q.month))&&(!q.native||s.hasPublishedReadings||s.readings?.length||allBlocks(data.biographies.get(s.id)).some(block=>block.kind==='quotation'))&&(!q.death||data.biographies.get(s.id)?.death.status===q.death)&&words.every(w=>norm([deepSearch?.get(s.id)||'',s.name,s.sourceTitle,...(s.aliases||[]),s.region,...s.types,s.summary.text,...allBlocks(data.biographies.get(s.id)).map(block=>block.text)].join(' ')).includes(w))).sort((a,b)=>a.name.localeCompare(b.name));
      root.querySelector('#saints-count').textContent=`${found.length} of ${data.saints.length} profiles`;
      root.querySelector('#saints-results').innerHTML=found.length?found.map(s=>`<article class="saint-card" data-saint-card="${esc(s.id)}">${window.OrthodoxVisuals.picture(data.images.get(s.id),{card:true,title:s.name,href:"#/saint/"+s.id})}<div class="saint-card-text"><h2><a href="#/saint/${esc(s.id)}">${esc(s.name)}</a></h2><p class="saint-card-meta">${esc(s.era)} · ${esc(s.region)}</p><p>${s.types.map(esc).join(' · ')}</p>${data.biographies.get(s.id)?`<p class="saint-card-death">${esc(data.biographies.get(s.id).death.label)}</p>`:''}<p>${esc(commemoration(s))}${s.readings?.length?` · ${s.readings.length} additional reading${s.readings.length===1?'':'s'}`:''}</p></div>${data.images.get(s.id)?`<p class="saint-card-image-credit">${window.OrthodoxVisuals.credit(data.images.get(s.id))}</p>`:''}</article>`).join(''):'<div class="empty"><h2>No matching saints</h2><p>Change the search or reset filters.</p></div>';
      if(display==='timeline'&&found.length)root.querySelector('#saints-results').innerHTML=timeline(found);const p=new URLSearchParams();if(display==='timeline')p.set('view','timeline');for(const [key,value]of Object.entries(q))if(value)p.set(key,value);history.replaceState(null,'','#/saints'+(p.size?'?'+p.toString():''));
    }
    on('submit',e=>e.preventDefault());on('input',e=>{if(e.target.id==='saints-q'){q.q=e.target.value;render();}});on('change',e=>{const key=e.target.id.replace('saints-','');if(key in q&&key!=='q'){q[key]=key==='native'?(e.target.checked?'yes':''):e.target.value;render();}});on('click',e=>{const viewButton=e.target.closest('[data-saints-view]');if(viewButton){display=viewButton.dataset.saintsView;root.querySelectorAll('[data-saints-view]').forEach(button=>button.setAttribute('aria-pressed',String(button===viewButton)));render();return;}if(e.target.closest('[data-saints-reset]')){Object.keys(q).forEach(k=>q[k]='');root.querySelectorAll('select,input').forEach(el=>{if(el.type==='checkbox')el.checked=false;else el.value='';});render();}});render();
  }
  return {load,mount,unmount};
})();
